### 2. `components/AdminView.tsx`
(Amministrazione completa con menu griglia, gestione spese e reset cassa)

```tsx
import React, { useState, useMemo } from 'react';
import { Order, Till, TillColors, Product, StaffMember, CashMovement, AdminUser, Shift, TombolaConfig } from '../types';
import { User } from 'firebase/auth';
import { BackArrowIcon, TrashIcon, SaveIcon, EditIcon, ListIcon, BoxIcon, StaffIcon, CashIcon, SettingsIcon, StarIcon, GoogleIcon, UserPlusIcon } from './Icons';
import ProductManagement from './ProductManagement';
import StaffManagement from './StaffManagement';
import StockControl from './StockControl';
import CashManagement from './CashManagement';

interface AdminViewProps {
    onGoBack: () => void;
    orders: Order[];
    tills: Till[];
    tillColors: TillColors;
    products: Product[];
    staff: StaffMember[];
    cashMovements: CashMovement[];
    onUpdateTillColors: (colors: TillColors) => Promise<void>;
    onDeleteOrders: (orderIds: string[], adminEmail: string) => Promise<void>;
    onPermanentDeleteOrder: (orderId: string) => Promise<void>;
    onUpdateOrder: (order: Order) => Promise<void>;
    onAddProduct: (p: Omit<Product, 'id'>) => Promise<void>;
    onUpdateProduct: (p: Product) => Promise<void>;
    onDeleteProduct: (id: string) => Promise<void>;
    onAddStaff: (s: Omit<StaffMember, 'id'>) => Promise<void>;
    onUpdateStaff: (s: StaffMember) => Promise<void>;
    onDeleteStaff: (id: string) => Promise<void>;
    onAddCashMovement: (m: Omit<CashMovement, 'id'>) => Promise<void>;
    onStockPurchase: (productId: string, quantity: number, unitCost: number) => Promise<void>;
    onStockCorrection: (productId: string, newStock: number) => Promise<void>;
    onResetCash: () => Promise<void>;
    onMassDelete: (date: string, type: 'orders' | 'movements') => Promise<void>;

    // Auth
    isAuthenticated: boolean;
    currentUser: User | null;
    onLogin: () => void;
    onLogout: () => void;
    adminList: AdminUser[];
    onAddAdmin: (email: string) => Promise<void>;
    onRemoveAdmin: (id: string) => Promise<void>;

    // Tombola
    tombolaConfig?: TombolaConfig;
    onUpdateTombolaConfig: (cfg: TombolaConfig) => Promise<void>;
}

type AdminTab = 'movements' | 'stock' | 'products' | 'staff' | 'cash' | 'settings' | 'admins';

const AdminView: React.FC<AdminViewProps> = ({ 
    onGoBack, orders, tills, tillColors, products, staff, cashMovements,
    onUpdateTillColors, onDeleteOrders, onPermanentDeleteOrder, onUpdateOrder,
    onAddProduct, onUpdateProduct, onDeleteProduct,
    onAddStaff, onUpdateStaff, onDeleteStaff,
    onAddCashMovement, onStockPurchase, onStockCorrection, onResetCash, onMassDelete,
    isAuthenticated, currentUser, onLogin, onLogout, adminList, onAddAdmin, onRemoveAdmin,
    tombolaConfig, onUpdateTombolaConfig
}) => {
    const [activeTab, setActiveTab] = useState<AdminTab>('movements');

    // States for Movements
    const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
    const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState<{ total: number, date: string, time: string }>({ total: 0, date: '', time: '' });

    // Movement Filters
    const [movFilterDate, setMovFilterDate] = useState('');
    const [movFilterShift, setMovFilterShift] = useState<Shift | 'all'>('all');

    // Mass Delete
    const [massDeleteDate, setMassDeleteDate] = useState('');

    // States for Settings
    const [colors, setColors] = useState<TillColors>(tillColors);

    // States for Admin Mgmt
    const [newAdminEmail, setNewAdminEmail] = useState('');
    const [tombolaPrice, setTombolaPrice] = useState(tombolaConfig?.ticketPrice || 5);

    // Calcolo Super Admin (il primo in lista è il Super Admin)
    const sortedAdmins = useMemo(() => [...adminList].sort((a,b) => a.timestamp.localeCompare(b.timestamp)), [adminList]);
    const isSuperAdmin = currentUser && sortedAdmins.length > 0 && currentUser.email === sortedAdmins[0].email;

    // Filtri Movimenti
    const filteredOrders = useMemo(() => {
        return orders.filter(o => {
            if (movFilterDate) {
                const orderDate = new Date(o.timestamp).toISOString().split('T')[0];
                if (orderDate !== movFilterDate) return false;
            }
            if (movFilterShift !== 'all') {
                const staffMember = staff.find(s => s.id === o.staffId);
                if (!staffMember || staffMember.shift !== movFilterShift) return false;
            }
            return true;
        });
    }, [orders, movFilterDate, movFilterShift, staff]);

    const globalActiveOrders = useMemo(() => orders.filter(o => !o.isDeleted), [orders]);
    const totalRevenue = globalActiveOrders.reduce((sum, o) => sum + o.total, 0);
    const totalWithdrawals = cashMovements.reduce((sum, m) => sum + m.amount, 0);
    const currentBalance = totalRevenue - totalWithdrawals;

    const toggleOrderSelection = (id: string) => {
        const newSet = new Set(selectedOrderIds);
        if (newSet.has(id)) newSet.delete(id);
        else newSet.add(id);
        setSelectedOrderIds(newSet);
    };

    const toggleAllSelection = () => {
        if (selectedOrderIds.size === filteredOrders.length) {
            setSelectedOrderIds(new Set());
        } else {
            setSelectedOrderIds(new Set(filteredOrders.map(o => o.id)));
        }
    };

    const handleBulkDelete = async () => {
        if (selectedOrderIds.size === 0) return;
        if (window.confirm(`Sei sicuro di voler annullare ${selectedOrderIds.size} movimenti?`)) {
            await onDeleteOrders(Array.from(selectedOrderIds), currentUser?.email || 'Admin');
            setSelectedOrderIds(new Set());
        }
    };

    const handleSingleDelete = async (orderId: string) => {
        if (window.confirm("Sei sicuro di voler annullare questo movimento?")) {
            await onDeleteOrders([orderId], currentUser?.email || 'Admin');
        }
    };

    const handlePermanentDelete = async (orderId: string) => {
        if (window.confirm("ELIMINAZIONE DEFINITIVA. Questa operazione non può essere annullata. Procedere?")) {
            await onPermanentDeleteOrder(orderId);
        }
    };

    const startEditOrder = (order: Order) => {
        const dateObj = new Date(order.timestamp);
        setEditingOrderId(order.id);
        setEditForm({
            total: order.total,
            date: dateObj.toISOString().split('T')[0],
            time: dateObj.toTimeString().slice(0, 5)
        });
    };

    const saveEditOrder = async () => {
        if (!editingOrderId) return;
        const originalOrder = orders.find(o => o.id === editingOrderId);
        if (!originalOrder) return;
        const newTimestamp = new Date(`${editForm.date}T${editForm.time}`).toISOString();
        await onUpdateOrder({ ...originalOrder, total: editForm.total, timestamp: newTimestamp });
        setEditingOrderId(null);
    };

    const handleColorChange = (tillId: string, color: string) => {
        setColors(prev => ({ ...prev, [tillId]: color }));
    };

    const saveSettings = async () => {
        await onUpdateTillColors(colors);
        alert('Impostazioni salvate!');
    };

    const handleAddAdminSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        if(!newAdminEmail.trim()) return;
        await onAddAdmin(newAdminEmail.trim());
        setNewAdminEmail('');
    };

    const handleMassDelete = async (type: 'orders' | 'movements') => {
        if (!massDeleteDate) return alert("Seleziona una data limite.");
        if (window.confirm(`ATTENZIONE: Stai per eliminare DEFINITIVAMENTE tutti i record antecedenti al ${massDeleteDate}. Questa azione è irreversibile. Confermi?`)) {
            await onMassDelete(massDeleteDate, type);
        }
    };

    const handleUpdateTombolaPrice = async () => {
        await onUpdateTombolaConfig({ ...tombolaConfig, ticketPrice: Number(tombolaPrice) });
        alert("Prezzo cartella aggiornato!");
    };

    const TabButton = ({ tab, label, icon }: { tab: AdminTab, label: string, icon: React.ReactNode }) => (
        <button 
            onClick={() => setActiveTab(tab)} 
            className={`
                flex flex-col items-center justify-center p-1.5 rounded-lg transition-all w-14 h-14 md:w-16 md:h-16 text-[8px] md:text-[9px] font-bold gap-1
                ${activeTab === tab 
                    ? 'bg-red-500 text-white shadow-md scale-105' 
                    : 'bg-white text-slate-500 hover:bg-red-50 hover:text-red-500 border border-slate-100'
                }
            `}
        >
            <div className={`${activeTab === tab ? 'text-white' : 'text-slate-400'} transform scale-75 md:scale-90`}>
                {icon}
            </div>
            <span className="text-center leading-tight">{label}</span>
        </button>
    );

    if (!isAuthenticated) {
        return (
            <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4">
                <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full text-center border-t-4 border-red-500">
                    <h2 className="text-2xl font-bold mb-6 text-slate-800">Area Amministrativa</h2>
                    <div className="flex gap-2">
                         <button type="button" onClick={onGoBack} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl">Indietro</button>
                         <button type="button" onClick={onLogin} className="flex-1 py-3 bg-white border border-slate-200 text-slate-700 font-bold rounded-xl hover:bg-slate-50 flex items-center justify-center gap-2 shadow-sm">
                            <GoogleIcon className="h-5 w-5" /> Accedi con Google
                         </button>
                    </div>
                </div>
            </div>
        );
    }

    return (
        <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
            <header className="bg-white border-b border-slate-200 p-2 sticky top-0 z-50">
                <div className="flex flex-col gap-2 max-w-7xl mx-auto w-full">

                    {/* TOP BAR */}
                    <div className="flex items-center justify-between w-full">
                         <button onClick={onGoBack} className="flex items-center text-slate-500 hover:text-slate-800 font-bold gap-1 text-xs">
                            <BackArrowIcon className="h-3 w-3" /> Esci
                        </button>

                        <div className="bg-slate-800 text-white px-3 py-1 rounded-full shadow-lg flex flex-col items-center">
                            <span className="text-[8px] uppercase text-slate-400 font-bold tracking-wider">Saldo Cassa</span>
                            <span className="text-base font-black leading-none">€{currentBalance.toFixed(2)}</span>
                        </div>

                        <div className="text-right">
                             <p className="text-[8px] text-slate-400 uppercase font-bold">{isSuperAdmin ? 'Super Admin' : 'Admin'}</p>
                             <button onClick={onLogout} className="text-[9px] text-red-500 font-bold hover:underline">LOGOUT</button>
                        </div>
                    </div>

                    {/* NAVIGATION TABS - GRID */}
                    <div className="flex flex-wrap justify-center gap-1.5 w-full">
                        <TabButton tab="movements" label="Movimenti" icon={<ListIcon className="h-5 w-5" />} />
                        <TabButton tab="stock" label="Stock" icon={<BoxIcon className="h-5 w-5" />} />
                        <TabButton tab="products" label="Prodotti" icon={<StarIcon className="h-5 w-5" />} />
                        <TabButton tab="staff" label="Staff" icon={<StaffIcon className="h-5 w-5" />} />
                        <TabButton tab="cash" label="Cassa" icon={<CashIcon className="h-5 w-5" />} />
                        <TabButton tab="settings" label="Config" icon={<SettingsIcon className="h-5 w-5" />} />
                        <TabButton tab="admins" label="Admin" icon={<UserPlusIcon className="h-5 w-5" />} />
                    </div>
                </div>
            </header>

            <main className="flex-grow p-4 max-w-7xl mx-auto w-full">

                {activeTab === 'movements' && (
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="p-4 border-b border-slate-100 bg-slate-50">
                            <div className="flex flex-wrap gap-4 items-end justify-between">
                                <h2 className="font-bold text-lg text-slate-700">Gestione Movimenti</h2>
                                <div className="flex gap-2 items-center">
                                    <div>
                                        <label className="text-[8px] uppercase font-bold text-slate-400 block">Data</label>
                                        <input type="date" value={movFilterDate} onChange={e => setMovFilterDate(e.target.value)} className="border rounded px-2 py-1 text-xs bg-white" />
                                    </div>
                                    <div>
                                        <label className="text-[8px] uppercase font-bold text-slate-400 block">Turno</label>
                                        <select value={movFilterShift} onChange={e => setMovFilterShift(e.target.value as any)} className="border rounded px-2 py-1 text-xs bg-white">
                                            <option value="all">Tutti</option>
                                            <option value="a">A</option>
                                            <option value="b">B</option>
                                            <option value="c">C</option>
                                            <option value="d">D</option>
                                        </select>
                                    </div>
                                </div>
                            </div>
                            {selectedOrderIds.size > 0 && (
                                <button onClick={handleBulkDelete} className="mt-3 w-full bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg font-bold text-xs flex items-center justify-center gap-2"><TrashIcon className="h-3 w-3" /> Annulla ({selectedOrderIds.size})</button>
                            )}
                        </div>
                        <div className="overflow-x-auto max-h-[60vh]">
                            <table className="w-full text-left text-slate-600 text-xs">
                                <thead className="bg-slate-100 text-slate-800 uppercase text-[10px] sticky top-0 z-10">
                                    <tr>
                                        <th className="p-2 w-8"><input type="checkbox" checked={selectedOrderIds.size === filteredOrders.length && filteredOrders.length > 0} onChange={toggleAllSelection} className="rounded text-red-500 focus:ring-red-500" /></th>
                                        <th className="p-2">Data</th>
                                        <th className="p-2">Info</th>
                                        <th className="p-2 text-right">Totale</th>
                                        <th className="p-2 text-center">Stato</th>
                                        <th className="p-2 text-center">Azioni</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {filteredOrders.map(order => (
                                        <tr key={order.id} className={`hover:bg-slate-50 ${order.isDeleted ? 'bg-red-50' : ''}`}>
                                            <td className="p-2"><input type="checkbox" checked={selectedOrderIds.has(order.id)} onChange={() => toggleOrderSelection(order.id)} className="rounded text-red-500 focus:ring-red-500" /></td>
                                            <td className="p-2 whitespace-nowrap text-[10px]">
                                                {editingOrderId === order.id ? (
                                                    <div className="flex flex-col gap-1"><input type="date" value={editForm.date} onChange={e => setEditForm({...editForm, date: e.target.value})} className="border rounded px-1" /><input type="time" value={editForm.time} onChange={e => setEditForm({...editForm, time: e.target.value})} className="border rounded px-1" /></div>
                                                ) : new Date(order.timestamp).toLocaleString('it-IT')}
                                                {order.deletedBy && (
                                                    <div className="text-[8px] text-red-500 italic mt-0.5">Del: {order.deletedBy}</div>
                                                )}
                                            </td>
                                            <td className="p-2">
                                                <div className={`text-[10px] font-bold ${order.isDeleted ? 'text-red-800 line-through' : 'text-slate-700'}`}>{order.staffName}</div>
                                                <div className="text-[8px] text-slate-400 uppercase">Cassa {order.tillId}</div>
                                            </td>
                                            <td className="p-2 text-right font-bold text-slate-800">
                                                 {editingOrderId === order.id ? <input type="number" step="0.01" value={editForm.total} onChange={e => setEditForm({...editForm, total: parseFloat(e.target.value)})} className="border rounded px-1 w-16 text-right" /> : <span className={order.isDeleted ? 'line-through opacity-50' : ''}>€{order.total.toFixed(2)}</span>}
                                            </td>
                                            <td className="p-2 text-center">
                                                {order.isDeleted ? <span className="text-red-500 font-bold text-[8px] uppercase border border-red-200 bg-red-100 px-1 rounded">ANNULLATO</span> : <span className="text-green-500 font-bold text-[8px] uppercase">OK</span>}
                                            </td>
                                            <td className="p-2 flex justify-center gap-2">
                                                {editingOrderId === order.id ? (
                                                    <button onClick={saveEditOrder}><SaveIcon className="h-4 w-4 text-green-600" /></button>
                                                ) : (
                                                    <>
                                                        {!order.isDeleted && <button onClick={() => startEditOrder(order)}><EditIcon className="h-3 w-3 text-blue-400" /></button>}

                                                        {!order.isDeleted && <button onClick={() => handleSingleDelete(order.id)}><TrashIcon className="h-3 w-3 text-red-500" /></button>}

                                                        {order.isDeleted && isSuperAdmin && (
                                                            <button onClick={() => handlePermanentDelete(order.id)} title="Elimina Definitivamente"><TrashIcon className="h-3 w-3 text-slate-800" /></button>
                                                        )}
                                                    </>
                                                )}
                                            </td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {activeTab === 'stock' && <StockControl products={products} onStockPurchase={onStockPurchase} onStockCorrection={onStockCorrection} />}
                {activeTab === 'products' && <ProductManagement products={products} onAddProduct={onAddProduct} onUpdateProduct={onUpdateProduct} onDeleteProduct={onDeleteProduct} />}
                {activeTab === 'staff' && <StaffManagement staff={staff} onAddStaff={onAddStaff} onUpdateStaff={onUpdateStaff} onDeleteStaff={onDeleteStaff} />}
                {activeTab === 'cash' && <CashManagement orders={orders} movements={cashMovements} onAddMovement={onAddCashMovement} onResetCash={onResetCash} isSuperAdmin={isSuperAdmin} />}

                {activeTab === 'settings' && (
                    <div className="space-y-6">
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
