    const formatTicketToGrid = (numbers: number[]) => {
        // Questa è una simulazione visiva. In un sistema reale, la cartella nasce già strutturata.
        // Qui prendiamo i 15 numeri e li distribuiamo in 3 righe cercando di rispettare le colonne.
        const grid: (number | null)[][] = [[], [], []];
        const cols: number[][] = Array.from({length: 9}, () => []);

        // Distribuisci nelle colonne (decadi)
        numbers.forEach(n => {
            const colIdx = n === 90 ? 8 : Math.floor(n / 10);
            cols[colIdx].push(n);
        });

        // Distribuisci nelle righe (algoritmo semplificato per visualizzazione)
        // Riempie le righe bilanciando (5 numeri per riga)
        let currentRow = 0;
        let numbersInRow = 0;

