}

const TillSelection: React.FC<TillSelectionProps> = ({ tills, onSelectTill, onSelectReports, onSelectAdmin, tillColors }) => {

    // Generazione emoji cadenti - Più fitte e varie
    const fallingEmojis = useMemo(() => {
        // Mix di cibo e "fiocchi" (pallini bianchi) per effetto neve
        const emojis = ['☕', '🥐', '🍰', '🍹', '🍕', '🍔', '🍺', '❄️', '❄️', '❄️']; 
        return Array.from({ length: 60 }).map((_, i) => ({
            id: i,
            char: emojis[Math.floor(Math.random() * emojis.length)],
            left: `${Math.random() * 100}%`,
            duration: `${Math.random() * 15 + 10}s`, // Tra 10s e 25s
            delay: `${Math.random() * 15}s`, // Ritardo casuale per non farle partire tutte insieme
            size: `${Math.random() * 0.8 + 0.5}rem` // Piccole
        }));
    }, []);

    return (
        <div className="flex flex-col min-h-screen bg-slate-50 relative overflow-hidden font-sans">

            {/* SFONDO EMOJI CADENTI */}
            <div className="emoji-rain-container opacity-30 pointer-events-none">
                {fallingEmojis.map(emoji => (
                    <span 
                        key={emoji.id} 
                        className="falling-emoji"
                        style={{ 
                            left: emoji.left, 
                            animationDuration: emoji.duration, 
                            animationDelay: emoji.delay,
                            fontSize: emoji.size
                        }}
                    >
                        {emoji.char}
                    </span>
                ))}
            </div>

            <div className="flex-grow flex flex-col items-center justify-center p-2 z-10 w-full max-w-4xl mx-auto pb-16">

                {/* LOGO */}
                <div className="mb-2 relative group">
                    <img 
                        src="/logo.png" 
                        alt="Logo" 
                        className="h-16 w-auto object-contain drop-shadow-md transition-transform duration-500 hover:scale-105"
                        onError={(e) => {
                            (e.target as HTMLImageElement).style.display = 'none';
                        }}
                    />
                </div>

                <div className="text-center mb-4">
                    <h1 className="flex flex-col items-center leading-none">
                        <span className="text-3xl md:text-4xl font-black text-slate-800 tracking-tighter mb-1 drop-shadow-sm">
                            BAR VVF
                        </span>
                        <span className="text-xl md:text-2xl font-extrabold text-primary tracking-tight drop-shadow-sm">
                            Montepulciano
                        </span>
                    </h1>
                    <p className="text-slate-500 font-medium text-[10px] md:text-xs mt-1 bg-white/90 px-3 py-1 rounded-full inline-block backdrop-blur-sm shadow-sm border border-slate-100">
                        Scegli il turno per iniziare
                    </p>
                </div>

                {/* GRIGLIA PULSANTI CASSE */}
                <div className="flex flex-wrap justify-center gap-2 w-full mb-3 px-2">
                    {tills.map((till) => {
                        const bgColor = tillColors[till.id] || '#f97316';

                        return (
                            <button
                                key={till.id}
                                onClick={() => onSelectTill(till.id)}
                                className="group relative bg-white rounded-xl p-1 shadow-md hover:shadow-xl hover:-translate-y-1 transition-all duration-300 ease-out flex flex-col items-center justify-center w-16 h-20 border border-slate-100"
                            >
                                <div 
                                    className="w-10 h-10 rounded-full flex items-center justify-center shadow-inner mb-1 transition-transform duration-300 group-hover:scale-110" 
                                    style={{ backgroundColor: bgColor }}
                                >
                                    <span className="text-xl font-black text-white select-none">
                                        {till.shift.toUpperCase()}
                                    </span>
                                </div>
                                <span className="text-[9px] font-bold text-slate-700 leading-tight">
                                    {till.name}
                                </span>
                            </button>
                        );
                    })}
                </div>

                {/* MENU FUNZIONI */}
                <div className="flex gap-2 w-full justify-center px-2 flex-wrap mb-3">
                    <button
                        onClick={onSelectReports}
                        className="bg-white w-16 h-12 rounded-xl shadow-md hover:shadow-lg border border-slate-100 text-slate-600 font-bold flex flex-col items-center justify-center gap-0.5 hover:bg-slate-50 transition-all active:scale-95"
                    >
                        <ModernChartIcon className="h-4 w-4 text-primary" />
                        <span className="text-[8px] uppercase">Report</span>
                    </button>

                    <button
                        onClick={onSelectAdmin}
                        className="bg-white w-12 h-12 rounded-xl shadow-md hover:shadow-lg border border-slate-100 text-slate-400 hover:text-slate-800 hover:bg-slate-50 transition-all active:scale-95 flex items-center justify-center"
                        title="Area Riservata"
                    >
                        <LockIcon className="h-4 w-4" />
                    </button>
                </div>
            </div>

            {/* FOOTER FISSO */}
            <div className="fixed bottom-0 left-0 w-full bg-white/95 backdrop-blur-md border-t border-slate-200 py-2 text-center z-50 shadow-lg">
                <p className="text-[10px] text-slate-400 font-medium">
                    Gestionale Bar v3.0 | <span className="font-bold text-slate-500">Fabbrini M.</span>
                </p>
            </div>
        </div>
    );
};

export default TillSelection;

Perfetto, questa è un'ottima mossa organizzativa! Creiamo una sezione **"Extra"** all'interno dell'Admin, che fungerà da "Hub" per tutti i giochi e le attività speciali future (non solo la Tombola).

**Ecco il piano d'azione:**

1.  **Nuovo Componente `ExtrasHub`**:
    *   Sarà una pagina "Vetrina" all'interno dell'Admin.
    *   Mostrerà delle "Card" eleganti per ogni gioco disponibile (al momento solo "Tombola 2025").
    *   Cliccando sulla card, si entrerà nella schermata del gioco specifico.

2.  **Modifiche all'Admin (`AdminView`)**:
    *   Aggiungerò una nuova tab **"Extra"** nel menu principale (quello con le icone).
    *   Rimuoverò il pulsante "Tombola" diretto, spostandolo dentro questa nuova sezione.

3.  **Navigazione**:
    *   Admin -> Tab "Extra" -> `ExtrasHub` -> Click su "Tombola" -> `TombolaView`.

