                                        <button onClick={() => setBuyQuantity(6)} className={`flex-1 py-2 rounded font-bold text-xs ${buyQuantity === 6 ? 'bg-yellow-400 text-red-900 shadow-md' : 'bg-white/10 hover:bg-white/20'}`}>6x (€{config.ticketPriceBundle})</button>
