                                </div>
                                <button onClick={handleUpdateTombolaConfig} className="bg-indigo-600 text-white px-4 py-2 rounded font-bold hover:bg-indigo-700 mt-4 w-full">Salva Configurazione Tombola</button>
                            </div>
                        )}
                     </div>
                )}
            </main>
        </div>
    );
};

