            const current = playersMap.get(t.playerId) || { 
                id: t.playerId, 
                name: t.playerName || 'Sconosciuto', 
                icon: staff.find(s => s.id === t.playerId)?.icon || '👤', 
                ticketCount: 0, 
                spent: 0, 
                wins: 0 
            };
            current.ticketCount++;

