interface TillSelectionProps {
    tills: Till[];
    onSelectTill: (tillId: string) => void;
    onSelectReports: () => void;
    onSelectAdmin: () => void;
    onSelectTombola: () => void;
    tillColors: TillColors;
    seasonalityConfig?: SeasonalityConfig;
}

const TillSelection: React.FC<TillSelectionProps> = ({ tills, onSelectTill, onSelectReports, onSelectAdmin, tillColors, seasonalityConfig }) => {

    // Verifica se attivo e nel range
    const isSeasonActive = useMemo(() => {
        if (!seasonalityConfig?.isActive || !seasonalityConfig?.startDate || !seasonalityConfig?.endDate) return false;
        const now = new Date();
        const start = new Date(seasonalityConfig.startDate);
        const end = new Date(seasonalityConfig.endDate);
        end.setHours(23, 59, 59);
        return now >= start && now <= end;
    }, [seasonalityConfig]);

    const bgColor = isSeasonActive ? seasonalityConfig?.backgroundColor : '#f8fafc'; // Default slate-50
    const animationType = isSeasonActive ? seasonalityConfig?.animationType : 'none';
    const emojis = isSeasonActive && seasonalityConfig?.emojis.length ? seasonalityConfig.emojis : ['☕', '🥐', '🍹'];

    // Generazione particelle
    const particles = useMemo(() => {
        if (animationType === 'none') return [];

        const count = animationType === 'rain' ? 80 : 40;

        return Array.from({ length: count }).map((_, i) => {
            const style: any = {
                left: `${Math.random() * 100}%`,
                fontSize: `${Math.random() * 1 + 0.5}rem`,
                animationDelay: `${Math.random() * 5}s`,
            };

            if (animationType === 'snow') {
                style.animationName = 'fall';
                style.animationDuration = `${Math.random() * 10 + 10}s`; // Lento
            } else if (animationType === 'rain') {
                style.animationName = 'fall';
                style.animationDuration = `${Math.random() * 2 + 1}s`; // Veloce
            } else if (animationType === 'float') {
                style.animationName = 'float'; // Nuovo keyframe
                style.animationDuration = `${Math.random() * 10 + 15}s`;
                style.top = `${Math.random() * 100}%`; // Partono sparsi
            }

            return { id: i, char: emojis[Math.floor(Math.random() * emojis.length)], style };
        });
    }, [animationType, emojis]);

    return (
        <div className="flex flex-col min-h-screen relative overflow-hidden font-sans transition-colors duration-1000" style={{ backgroundColor: bgColor }}>

            {/* CANVAS ANIMAZIONI */}
            {animationType !== 'none' && (
                <div className="emoji-rain-container opacity-40 pointer-events-none">
