                        <span 
                            key={p.id} 
                            className="absolute"
                            style={{ 
                                ...p.style,
                                animationTimingFunction: animationType === 'float' ? 'ease-in-out' : 'linear',
                                animationIterationCount: 'infinite'
                            }}
                        >
                            {p.char}
                        </span>
                    ))}
