```tsx
import React, { useState, useEffect, useCallback } from 'react';
import { db, auth, googleProvider } from './firebaseConfig';
import { collection, onSnapshot, doc, getDocs, writeBatch, runTransaction, addDoc, updateDoc, deleteDoc, setDoc, orderBy, query, getDoc, where } from 'firebase/firestore';
import { signInWithPopup, signOut, onAuthStateChanged, User } from 'firebase/auth';
import TillSelection from './components/TillSelection';
import TillView from './components/TillView';
import ReportsView from './components/ReportsView';
import AdminView from './components/AdminView';
import TombolaView from './components/TombolaView';
import { TILLS, INITIAL_MENU_ITEMS, INITIAL_STAFF_MEMBERS } from './constants';
import { Till, Product, StaffMember, Order, TillColors, CashMovement, AdminUser, TombolaConfig, TombolaTicket, TombolaWin, SeasonalityConfig } from './types';

type View = 'selection' | 'till' | 'reports' | 'admin' | 'tombola';

// Helper per mescolare un array
const shuffleArray = (array: any[]) => {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
};

const App: React.FC = () => {
    const [view, setView] = useState<View>('selection');
    const [selectedTillId, setSelectedTillId] = useState<string | null>(null);
    const [isLoading, setIsLoading] = useState(true);

    // Auth State
    const [currentUser, setCurrentUser] = useState<User | null>(null);
    const [isAdmin, setIsAdmin] = useState(false);
    const [adminList, setAdminList] = useState<AdminUser[]>([]);

    const [products, setProducts] = useState<Product[]>([]);
    const [staff, setStaff] = useState<StaffMember[]>([]);
    const [orders, setOrders] = useState<Order[]>([]);
    const [cashMovements, setCashMovements] = useState<CashMovement[]>([]);
    const [tillColors, setTillColors] = useState<TillColors>({});

    // Tombola State
    const [tombolaConfig, setTombolaConfig] = useState<TombolaConfig | undefined>(undefined);
    const [tombolaTickets, setTombolaTickets] = useState<TombolaTicket[]>([]);
    const [tombolaWins, setTombolaWins] = useState<TombolaWin[]>([]);

    // Seasonality State
    const [seasonalityConfig, setSeasonalityConfig] = useState<SeasonalityConfig | undefined>(undefined);

    // Calcolo Super Admin
    const isSuperAdmin = currentUser && adminList.length > 0 && currentUser.email === adminList.sort((a,b) => a.timestamp.localeCompare(b.timestamp))[0].email;

    // Auth Listener
    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (user) => {
            setCurrentUser(user);
            if (user && user.email) {
                const adminsRef = collection(db, 'admins');
                const adminsSnapshot = await getDocs(adminsRef);
                if (adminsSnapshot.empty) {
                    await addDoc(adminsRef, { email: user.email, addedBy: 'SYSTEM_BOOTSTRAP', timestamp: new Date().toISOString() });
                    setIsAdmin(true);
                } else {
                    const q = query(adminsRef, where("email", "==", user.email));
                    const querySnapshot = await getDocs(q);
                    setIsAdmin(!querySnapshot.empty);
                }
            } else { setIsAdmin(false); }
        });
        return () => unsubscribe();
    }, []);

    // Data Listeners
    useEffect(() => {
        setIsLoading(true);
        const unsubProducts = onSnapshot(collection(db, 'products'), (s) => setProducts(s.docs.map(d => ({ ...d.data(), id: d.id } as Product))));
        const unsubStaff = onSnapshot(collection(db, 'staff'), (s) => setStaff(s.docs.map(d => ({ ...d.data(), id: d.id } as StaffMember))));
        const unsubOrders = onSnapshot(query(collection(db, 'orders'), orderBy('timestamp', 'desc')), (s) => { setOrders(s.docs.map(d => ({ ...d.data(), id: d.id } as Order))); setIsLoading(false); });
        const unsubCash = onSnapshot(query(collection(db, 'cash_movements'), orderBy('timestamp', 'desc')), (s) => setCashMovements(s.docs.map(d => ({ ...d.data(), id: d.id } as CashMovement))));
        const unsubAdmins = onSnapshot(collection(db, 'admins'), (s) => setAdminList(s.docs.map(d => ({ ...d.data(), id: d.id } as AdminUser))));
        const unsubSettings = onSnapshot(doc(db, 'settings', 'tillColors'), (d) => { if(d.exists()) setTillColors(d.data() as TillColors); });

        const unsubTombolaConfig = onSnapshot(doc(db, 'tombola', 'config'), (d) => { 
            if (d.exists()) setTombolaConfig(d.data() as TombolaConfig); 
            else setDoc(doc(db, 'tombola', 'config'), { 
                status: 'pending',
                maxTickets: 168,
                minTicketsToStart: 84,
                ticketPriceSingle: 1, 
                ticketPriceBundle: 5,
                jackpot: 0, 
                lastExtraction: new Date().toISOString(), 
                extractedNumbers: [] 
            }); 
        });
        const unsubTombolaTickets = onSnapshot(collection(db, 'tombola_tickets'), (s) => setTombolaTickets(s.docs.map(d => ({...d.data(), id: d.id} as TombolaTicket))));
        const unsubTombolaWins = onSnapshot(collection(db, 'tombola_wins'), (s) => setTombolaWins(s.docs.map(d => ({...d.data(), id: d.id} as TombolaWin))));

        // CONFIGURAZIONE STAGIONALE AVANZATA (4 STAGIONI)
        const unsubSeasonality = onSnapshot(doc(db, 'settings', 'seasonality'), (d) => { 
            if(d.exists()) setSeasonalityConfig(d.data() as SeasonalityConfig); 
            else {
                // Default robusto
                const defaultConfig: SeasonalityConfig = {
                    mode: 'auto',
                    currentManualSeason: 'winter',
                    seasons: {
                        winter: { name: 'Inverno', backgroundColor: '#1e293b', animationType: 'snow', emojis: ['❄️', '⛄', '🎄'] },
                        spring: { name: 'Primavera', backgroundColor: '#f0fdf4', animationType: 'float', emojis: ['🌸', '🦋', '🌱'] },
                        summer: { name: 'Estate', backgroundColor: '#fefce8', animationType: 'float', emojis: ['☀️', '🍦', '🌊'] },
                        autumn: { name: 'Autunno', backgroundColor: '#fff7ed', animationType: 'leaves', emojis: ['🍂', '🍄', '🌰'] }
                    }
                };
                setDoc(doc(db, 'settings', 'seasonality'), defaultConfig);
            }
        });

        return () => { unsubProducts(); unsubStaff(); unsubOrders(); unsubCash(); unsubAdmins(); unsubSettings(); unsubTombolaConfig(); unsubTombolaTickets(); unsubTombolaWins(); unsubSeasonality(); };
    }, []);

    // Seeding
    useEffect(() => {
        const seedDatabase = async () => {
            try {
                const productsSnap = await getDocs(collection(db, 'products'));
                if (productsSnap.empty) {
                    const batch = writeBatch(db);
                    INITIAL_MENU_ITEMS.forEach(item => batch.set(doc(db, 'products', item.id), item));
                    await batch.commit();
                }
                const staffSnap = await getDocs(collection(db, 'staff'));
                if (staffSnap.empty) {
                    const batch = writeBatch(db);
                    INITIAL_STAFF_MEMBERS.forEach(member => batch.set(doc(db, 'staff', member.id), member));
                    await batch.commit();
                }
            } catch (error) { console.error("Error seeding database:", error); }
        };
        seedDatabase();
    }, []);

    // Tombola Extraction
    useEffect(() => {
        const runTombolaExtraction = async () => {
            if (!tombolaConfig || !tombolaConfig.extractedNumbers || tombolaConfig.extractedNumbers.length >= 90) return;
            if (tombolaConfig.status !== 'active') return;

            const now = new Date().getTime();
            const last = new Date(tombolaConfig.lastExtraction).getTime();
            const diffHours = (now - last) / (1000 * 60 * 60);
            if (diffHours >= 2) {
                try {
                    await runTransaction(db, async (t) => {
                        const configRef = doc(db, 'tombola', 'config');
                        const configSnap = await t.get(configRef);
                        const currentConfig = configSnap.data() as TombolaConfig;
                        if (!currentConfig.extractedNumbers) currentConfig.extractedNumbers = [];

                        let nextNum;
                        do { nextNum = Math.floor(Math.random() * 90) + 1; } while (currentConfig.extractedNumbers.includes(nextNum));
                        const newExtracted = [...currentConfig.extractedNumbers, nextNum];

                        const ticketsSnap = await getDocs(collection(db, 'tombola_tickets'));
                        ticketsSnap.forEach(ticketDoc => {
                            const ticket = ticketDoc.data() as TombolaTicket;
                            if (!ticket.numbers) return;
                            const matches = ticket.numbers.filter(n => newExtracted.includes(n));
                            const count = matches.length;
                            if ([2,3,4,5,15].includes(count)) {
                                const type = count === 2 ? 'Ambo' : count === 3 ? 'Terno' : count === 4 ? 'Quaterna' : count === 5 ? 'Cinquina' : 'Tombola';
                                const winRef = doc(collection(db, 'tombola_wins'));
                                t.set(winRef, { ticketId: ticketDoc.id, playerName: ticket.playerName, type, numbers: matches, timestamp: new Date().toISOString() });
                            }
                        });
                        t.update(configRef, { lastExtraction: new Date().toISOString(), extractedNumbers: newExtracted });
                    });
                } catch (e) { console.error(e); }
            }
        };
        const interval = setInterval(runTombolaExtraction, 60000);
        return () => clearInterval(interval);
    }, [tombolaConfig]);

    const handleGoogleLogin = async () => { try { await signInWithPopup(auth, googleProvider); } catch (error) { alert("Errore login."); } };
    const handleLogout = async () => { await signOut(auth); setView('selection'); };
    const handleAddAdmin = async (email: string) => { if (isAdmin) await addDoc(collection(db, 'admins'), { email, addedBy: currentUser?.email, timestamp: new Date().toISOString() }); };
    const handleRemoveAdmin = async (id: string) => { if (isAdmin) await deleteDoc(doc(db, 'admins', id)); };

    const handleSelectTill = useCallback((tillId: string) => { setSelectedTillId(tillId); setView('till'); }, []);
    const handleSelectReports = useCallback(() => setView('reports'), []);
    const handleSelectAdmin = useCallback(() => setView('admin'), []);
    const handleSelectTombola = useCallback(() => setView('tombola'), []);
    const handleGoBack = useCallback(() => { setSelectedTillId(null); setView('selection'); }, []);

    const handleCompleteOrder = useCallback(async (newOrderData: Omit<Order, 'id'>) => {
        try {
            await runTransaction(db, async (t) => {
                const productDocs = await Promise.all(newOrderData.items.map(i => t.get(doc(db, 'products', i.product.id))));
                productDocs.forEach((d, i) => { if (!d.exists()) throw new Error(`Prod "${newOrderData.items[i].product.name}" mancante.`); });
                const orderRef = doc(collection(db, 'orders'));
                t.set(orderRef, { ...newOrderData, id: orderRef.id });
                productDocs.forEach((d, i) => t.update(d.ref, { stock: d.data().stock - newOrderData.items[i].quantity }));
            });
        } catch (error) { console.error(error); throw error; }
    }, []);

    const handleBuyTombolaTicket = async (staffId: string, quantity: number) => {
        if (!tombolaConfig) return;
        const currentTicketsCount = tombolaTickets.length;
        if (currentTicketsCount + quantity > tombolaConfig.maxTickets) {
            alert(`Impossibile acquistare. Rimangono solo ${tombolaConfig.maxTickets - currentTicketsCount} cartelle.`);
            return;
        }

        const staffMember = staff.find(s => s.id === staffId);
        if (!staffMember) return;

        let totalCost = quantity === 6 ? tombolaConfig.ticketPriceBundle : quantity * tombolaConfig.ticketPriceSingle;
        const revenue = totalCost * 0.20;
        const jackpotAdd = totalCost * 0.80;

        try {
            await runTransaction(db, async (t) => {
                if (quantity === 6) {
                    const allNumbers = shuffleArray(Array.from({ length: 90 }, (_, i) => i + 1));
                    for (let i = 0; i < 6; i++) {
                        const ticketNumbers = allNumbers.slice(i * 15, (i + 1) * 15).sort((a,b) => a - b);
                        const ticketRef = doc(collection(db, 'tombola_tickets'));
                        t.set(ticketRef, { playerId: staffId, playerName: staffMember.name, numbers: ticketNumbers, purchaseTime: new Date().toISOString() });
                    }
                } else {
                    for (let i = 0; i < quantity; i++) {
                        const ticketNumbers = generateSingleTicket();
                        const ticketRef = doc(collection(db, 'tombola_tickets'));
                        t.set(ticketRef, { playerId: staffId, playerName: staffMember.name, numbers: ticketNumbers, purchaseTime: new Date().toISOString() });
                    }
                }

                t.update(doc(db, 'tombola', 'config'), { jackpot: tombolaConfig.jackpot + jackpotAdd });
                const cashRef = doc(collection(db, 'cash_movements'));
                t.set(cashRef, { amount: totalCost, reason: `Tombola: ${quantity} cartelle (${staffMember.name})`, timestamp: new Date().toISOString(), type: 'deposit', category: 'tombola' });
                const barCashRef = doc(collection(db, 'cash_movements'));
                t.set(barCashRef, { amount: revenue, reason: `Utile Tombola (20%)`, timestamp: new Date().toISOString(), type: 'deposit', category: 'bar' });
            });
        } catch (e) { console.error(e); throw e; }
    };

    const generateSingleTicket = () => {
        const ticket: number[] = [];
        const cols: number[][] = Array.from({ length: 9 }, () => []);
        for (let i = 0; i < 9; i++) {
            const start = i * 10 + 1;
            const end = i === 8 ? 90 : (i + 1) * 10;
            for(let n=start; n <= end; n++) if(i===0 && n>9) continue; else cols[i].push(n);
        }
        let numbersCount = 0;
        while(numbersCount < 15) {
            const colIdx = Math.floor(Math.random() * 9);
            if(cols[colIdx].length > 0) {
                const numIdx = Math.floor(Math.random() * cols[colIdx].length);
                const num = cols[colIdx][numIdx];
                if(!ticket.includes(num)) {
                    ticket.push(num);
                    cols[colIdx].splice(numIdx, 1);
                    numbersCount++;
                }
            }
        }
        return ticket.sort((a,b) => a-b);
    };

    const handleUpdateTombolaConfig = async (cfg: TombolaConfig) => { await setDoc(doc(db, 'tombola', 'config'), cfg); };
    const handleTombolaStart = async () => { 
        if (!tombolaConfig) return;
        if (tombolaTickets.length < (tombolaConfig.minTicketsToStart || 0)) {
             if(!window.confirm(`Attenzione: vendute solo ${tombolaTickets.length} cartelle su min ${tombolaConfig.minTicketsToStart}. Avviare comunque?`)) return;
        }
        await updateDoc(doc(db, 'tombola', 'config'), { status: 'active', lastExtraction: new Date().toISOString() }); 
    };

    const handleTransferGameFunds = async (amount: number, gameName: string) => {
        if (amount <= 0) return;
        try {
            await runTransaction(db, async (t) => {
                if (gameName.toLowerCase().includes('tombola')) {
                    t.update(doc(db, 'tombola', 'config'), { jackpot: 0 });
                }
                const cashRef = doc(collection(db, 'cash_movements'));
                t.set(cashRef, {
                    amount: amount,
                    reason: `Versamento utile ${gameName}`,
                    timestamp: new Date().toISOString(),
                    type: 'deposit',
                    category: 'bar',
                    isDeleted: false
                });
            });
        } catch (error) { console.error("Error transferring funds:", error); }
    };

    const addProduct = async (d: any) => { await addDoc(collection(db, 'products'), { ...d, createdAt: new Date().toISOString(), createdBy: currentUser?.email || 'admin' }); };
    const updateProduct = async (p: any) => { const { id, ...d } = p; await updateDoc(doc(db, 'products', id), d); };
    const deleteProduct = async (id: string) => { await deleteDoc(doc(db, 'products', id)); };
    const addStaff = async (d: any) => { await addDoc(collection(db, 'staff'), d); };
    const updateStaff = async (s: any) => { const { id, ...d } = s; await updateDoc(doc(db, 'staff', id), d); };
    const deleteStaff = async (id: string) => { await deleteDoc(doc(db, 'staff', id)); };
    const addCashMovement = async (d: any) => { await addDoc(collection(db, 'cash_movements'), d); };
    const updateCashMovement = async (m: CashMovement) => { const { id, ...d } = m; await updateDoc(doc(db, 'cash_movements', id), d); };
    const deleteCashMovement = async (id: string, email: string) => { await updateDoc(doc(db, 'cash_movements', id), { isDeleted: true, deletedBy: email, deletedAt: new Date().toISOString() }); };
    const updateTillColors = async (c: TillColors) => { await setDoc(doc(db, 'settings', 'tillColors'), c, { merge: true }); };
    const deleteOrders = async (ids: string[], email: string) => { const batch = writeBatch(db); ids.forEach(id => batch.update(doc(db, 'orders', id), { isDeleted: true, deletedBy: email, deletedAt: new Date().toISOString() })); await batch.commit(); };
    const permanentDeleteOrder = async (id: string) => { await deleteDoc(doc(db, 'orders', id)); };
    const updateOrder = async (o: Order) => { const { id, ...d } = o; await updateDoc(doc(db, 'orders', id), d); };
    const handleStockPurchase = async (pid: string, qty: number, cost: number) => { const pRef = doc(db, 'products', pid); const pSnap = await getDoc(pRef); if(pSnap.exists()) { await updateDoc(pRef, { stock: pSnap.data().stock + qty, costPrice: cost }); await addDoc(collection(db, 'cash_movements'), { amount: qty*cost, reason: `Acquisto Stock: ${pSnap.data().name}`, timestamp: new Date().toISOString(), type: 'withdrawal', category: 'bar' }); } };
    const handleStockCorrection = async (pid: string, stock: number) => { await updateDoc(doc(db, 'products', pid), { stock }); };
    const handleResetCash = async () => { const batch = writeBatch(db); cashMovements.forEach(m => batch.update(doc(db, 'cash_movements', m.id), { amount: 0, reason: m.reason + ' (RESET)' })); await batch.commit(); };
    const handleMassDelete = async (date: string, type: 'orders'|'movements') => { const q = query(collection(db, type === 'orders' ? 'orders' : 'cash_movements'), where('timestamp', '<=', new Date(date).toISOString())); const s = await getDocs(q); const batch = writeBatch(db); s.docs.forEach(d => batch.delete(d.ref)); await batch.commit(); };
    const handleUpdateSeasonality = async (cfg: SeasonalityConfig) => { await setDoc(doc(db, 'settings', 'seasonality'), cfg); };

    const renderContent = () => {
        if (isLoading) return <div className="flex items-center justify-center min-h-screen"><div className="animate-spin rounded-full h-16 w-16 border-b-2 border-primary"></div></div>;
        switch (view) {
            case 'till': return <TillView till={TILLS.find(t=>t.id===selectedTillId)!} onGoBack={handleGoBack} products={products} allStaff={staff} allOrders={orders} onCompleteOrder={handleCompleteOrder} tillColors={tillColors} />;
            case 'reports': return <ReportsView onGoBack={handleGoBack} products={products} staff={staff} orders={orders} />;
            case 'tombola': 
                if (!tombolaConfig) return <div className="flex items-center justify-center min-h-screen"><div className="animate-spin rounded-full h-16 w-16 border-b-2 border-primary"></div></div>;
                return <TombolaView 
                onGoBack={handleGoBack} 
                config={tombolaConfig} 
                tickets={tombolaTickets} 
                wins={tombolaWins} 
                onBuyTicket={handleBuyTombolaTicket} 
                staff={staff} 
                onStartGame={handleTombolaStart} 
                isSuperAdmin={isSuperAdmin} 
                onTransferFunds={handleTransferGameFunds}
            />;
            case 'admin': return <AdminView 
                onGoBack={handleGoBack} 
                orders={orders} 
                tills={TILLS} 
                tillColors={tillColors} 
                products={products} 
                staff={staff} 
                cashMovements={cashMovements} 
                onUpdateTillColors={updateTillColors} 
                onDeleteOrders={deleteOrders} 
                onPermanentDeleteOrder={permanentDeleteOrder} 
                onUpdateOrder={updateOrder} 
                onAddProduct={addProduct} 
                onUpdateProduct={updateProduct} 
                onDeleteProduct={deleteProduct} 
                onAddStaff={addStaff} 
                onUpdateStaff={updateStaff} 
                onDeleteStaff={deleteStaff} 
                onAddCashMovement={addCashMovement} 
                onUpdateMovement={updateCashMovement} 
                onDeleteMovement={deleteCashMovement} 
                onStockPurchase={handleStockPurchase} 
                onStockCorrection={handleStockCorrection} 
                onResetCash={handleResetCash} 
                onMassDelete={handleMassDelete} 
                isAuthenticated={isAdmin} 
                currentUser={currentUser} 
                onLogin={handleGoogleLogin} 
                onLogout={handleLogout} 
                adminList={adminList} 
                onAddAdmin={handleAddAdmin} 
                onRemoveAdmin={handleRemoveAdmin} 
                tombolaConfig={tombolaConfig} 
                onUpdateTombolaConfig={handleUpdateTombolaConfig as any} 
                onNavigateToTombola={handleSelectTombola}
                seasonalityConfig={seasonalityConfig}
                onUpdateSeasonality={handleUpdateSeasonality}
            />;
            default: return <TillSelection tills={TILLS} onSelectTill={handleSelectTill} onSelectReports={handleSelectReports} onSelectAdmin={handleSelectAdmin} onSelectTombola={handleSelectTombola} tillColors={tillColors} seasonalityConfig={seasonalityConfig} />;
        }
    };

    return <div className="min-h-screen bg-slate-100 text-slate-800 font-sans">{renderContent()}</div>;
};

export default App;
```

### 3. `components/AdminView.tsx`
*(Interfaccia di configurazione con TAB per le 4 stagioni)*

```tsx
import React, { useState, useMemo } from 'react';
import { Order, Till, TillColors, Product, StaffMember, CashMovement, AdminUser, Shift, TombolaConfig, SeasonalityConfig, SeasonTheme } from '../types';
import { User } from 'firebase/auth';
import { BackArrowIcon, TrashIcon, SaveIcon, EditIcon, ListIcon, BoxIcon, StaffIcon, CashIcon, SettingsIcon, StarIcon, GoogleIcon, UserPlusIcon, TicketIcon, SparklesIcon } from './Icons';
import ProductManagement from './ProductManagement';
import StaffManagement from './StaffManagement';
import StockControl from './StockControl';
import CashManagement from './CashManagement';
import GamesHub from './GamesHub';

interface AdminViewProps {
    onGoBack: () => void;
    orders: Order[];
    tills: Till[];
    tillColors: TillColors;
    products: Product[];
    staff: StaffMember[];
    cashMovements: CashMovement[];
    onUpdateTillColors: (colors: TillColors) => Promise<void>;
    onDeleteOrders: (orderIds: string[], adminEmail: string) => Promise<void>;
    onPermanentDeleteOrder: (orderId: string) => Promise<void>;
    onUpdateOrder: (order: Order) => Promise<void>;
    onAddProduct: (p: Omit<Product, 'id'>) => Promise<void>;
    onUpdateProduct: (p: Product) => Promise<void>;
    onDeleteProduct: (id: string) => Promise<void>;
    onAddStaff: (s: Omit<StaffMember, 'id'>) => Promise<void>;
    onUpdateStaff: (s: StaffMember) => Promise<void>;
    onDeleteStaff: (id: string) => Promise<void>;
    onAddCashMovement: (m: Omit<CashMovement, 'id'>) => Promise<void>;
    onUpdateMovement: (m: CashMovement) => Promise<void>;
    onDeleteMovement: (id: string, email: string) => Promise<void>;
    onStockPurchase: (productId: string, quantity: number, unitCost: number) => Promise<void>;
    onStockCorrection: (productId: string, newStock: number) => Promise<void>;
    onResetCash: () => Promise<void>;
    onMassDelete: (date: string, type: 'orders' | 'movements') => Promise<void>;

    isAuthenticated: boolean;
    currentUser: User | null;
    onLogin: () => void;
    onLogout: () => void;
    adminList: AdminUser[];
    onAddAdmin: (email: string) => Promise<void>;
    onRemoveAdmin: (id: string) => Promise<void>;

    tombolaConfig?: TombolaConfig;
    onUpdateTombolaConfig: (cfg: Partial<TombolaConfig>) => Promise<void>;
    onNavigateToTombola: () => void;

    seasonalityConfig?: SeasonalityConfig;
    onUpdateSeasonality: (cfg: SeasonalityConfig) => Promise<void>;
}

type AdminTab = 'movements' | 'stock' | 'products' | 'staff' | 'cash' | 'settings' | 'admins' | 'extra';

const AdminView: React.FC<AdminViewProps> = ({ 
    onGoBack, orders, tills, tillColors, products, staff, cashMovements,
    onUpdateTillColors, onDeleteOrders, onPermanentDeleteOrder, onUpdateOrder,
    onAddProduct, onUpdateProduct, onDeleteProduct,
    onAddStaff, onUpdateStaff, onDeleteStaff,
    onAddCashMovement, onUpdateMovement, onDeleteMovement, onStockPurchase, onStockCorrection, onResetCash, onMassDelete,
    isAuthenticated, currentUser, onLogin, onLogout, adminList, onAddAdmin, onRemoveAdmin,
    tombolaConfig, onUpdateTombolaConfig, onNavigateToTombola,
    seasonalityConfig, onUpdateSeasonality
}) => {
    const [activeTab, setActiveTab] = useState<AdminTab>('movements');
    const [selectedOrderIds, setSelectedOrderIds] = useState<Set<string>>(new Set());
    const [editingOrderId, setEditingOrderId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState<{ total: number, date: string, time: string }>({ total: 0, date: '', time: '' });
    const [movFilterDate, setMovFilterDate] = useState('');
    const [movFilterShift, setMovFilterShift] = useState<Shift | 'all'>('all');
    const [massDeleteDate, setMassDeleteDate] = useState('');
    const [colors, setColors] = useState<TillColors>(tillColors);
    const [newAdminEmail, setNewAdminEmail] = useState('');
    const [tombolaPriceSingle, setTombolaPriceSingle] = useState(tombolaConfig?.ticketPriceSingle || 1);
    const [tombolaPriceBundle, setTombolaPriceBundle] = useState(tombolaConfig?.ticketPriceBundle || 5);
    const [tombolaMaxTickets, setTombolaMaxTickets] = useState(tombolaConfig?.maxTickets || 168);
    const [tombolaMinStart, setTombolaMinStart] = useState(tombolaConfig?.minTicketsToStart || 84);

    // Seasonality State
    const [seasonConfigForm, setSeasonConfigForm] = useState<SeasonalityConfig | null>(null);
    const [activeSeasonTab, setActiveSeasonTab] = useState<'winter'|'spring'|'summer'|'autumn'>('winter');
    const [emojiInput, setEmojiInput] = useState('');

    useMemo(() => {
        if (seasonalityConfig && !seasonConfigForm) {
            setSeasonConfigForm(seasonalityConfig);
            if (seasonalityConfig.seasons && seasonalityConfig.seasons.winter) {
                setEmojiInput(seasonalityConfig.seasons.winter.emojis.join(', '));
            }
        }
    }, [seasonalityConfig]);

    const sortedAdmins = useMemo(() => [...adminList].sort((a,b) => a.timestamp.localeCompare(b.timestamp)), [adminList]);
    const isSuperAdmin = currentUser && sortedAdmins.length > 0 && currentUser.email === sortedAdmins[0].email;

    const filteredOrders = useMemo(() => {
        return orders.filter(o => {
            if (movFilterDate) {
                const orderDate = new Date(o.timestamp).toISOString().split('T')[0];
                if (orderDate !== movFilterDate) return false;
            }
            if (movFilterShift !== 'all') {
                const staffMember = staff.find(s => s.id === o.staffId);
                if (!staffMember || staffMember.shift !== movFilterShift) return false;
            }
            return true;
        });
    }, [orders, movFilterDate, movFilterShift, staff]);

    const globalActiveOrders = useMemo(() => orders.filter(o => !o.isDeleted), [orders]);
    const totalRevenue = globalActiveOrders.reduce((sum, o) => sum + o.total, 0) || 0;

    const activeCashMovements = useMemo(() => cashMovements.filter(m => !m.isDeleted), [cashMovements]);
    const barMovements = activeCashMovements.filter(m => m.category === 'bar' || !m.category);

    const totalWithdrawals = barMovements.filter(m => m.type === 'withdrawal').reduce((sum, m) => sum + m.amount, 0) || 0;
    const totalDeposits = barMovements.filter(m => m.type === 'deposit').reduce((sum, m) => sum + m.amount, 0) || 0;
    const currentBalance = totalRevenue + totalDeposits - totalWithdrawals;

    const toggleOrderSelection = (id: string) => { const newSet = new Set(selectedOrderIds); if (newSet.has(id)) newSet.delete(id); else newSet.add(id); setSelectedOrderIds(newSet); };
    const toggleAllSelection = () => { if (selectedOrderIds.size === filteredOrders.length) setSelectedOrderIds(new Set()); else setSelectedOrderIds(new Set(filteredOrders.map(o => o.id))); };
    const handleBulkDelete = async () => { if (selectedOrderIds.size === 0) return; if (window.confirm(`Sei sicuro di voler annullare ${selectedOrderIds.size} movimenti?`)) { await onDeleteOrders(Array.from(selectedOrderIds), currentUser?.email || 'Admin'); setSelectedOrderIds(new Set()); } };
    const handleSingleDelete = async (orderId: string) => { if (window.confirm("Sei sicuro di voler annullare questo movimento?")) await onDeleteOrders([orderId], currentUser?.email || 'Admin'); };
    const handlePermanentDelete = async (orderId: string) => { if (window.confirm("ELIMINAZIONE DEFINITIVA. Procedere?")) await onPermanentDeleteOrder(orderId); };
    const startEditOrder = (order: Order) => { const dateObj = new Date(order.timestamp); setEditingOrderId(order.id); setEditForm({ total: order.total, date: dateObj.toISOString().split('T')[0], time: dateObj.toTimeString().slice(0, 5) }); };
    const saveEditOrder = async () => { if (!editingOrderId) return; const originalOrder = orders.find(o => o.id === editingOrderId); if (!originalOrder) return; const newTimestamp = new Date(`${editForm.date}T${editForm.time}`).toISOString(); await onUpdateOrder({ ...originalOrder, total: editForm.total, timestamp: newTimestamp }); setEditingOrderId(null); };
    const handleColorChange = (tillId: string, color: string) => setColors(prev => ({ ...prev, [tillId]: color }));
    const saveSettings = async () => { await onUpdateTillColors(colors); alert('Impostazioni salvate!'); };
    const handleAddAdminSubmit = async (e: React.FormEvent) => { e.preventDefault(); if(!newAdminEmail.trim()) return; await onAddAdmin(newAdminEmail.trim()); setNewAdminEmail(''); };
    const handleMassDelete = async (type: 'orders' | 'movements') => { if (!massDeleteDate) return alert("Seleziona data."); if (window.confirm(`ATTENZIONE: Eliminazione DEFINITIVA antecedenti a ${massDeleteDate}. Confermi?`)) await onMassDelete(massDeleteDate, type); };
    const handleUpdateTombolaConfig = async () => { await onUpdateTombolaConfig({ ticketPriceSingle: Number(tombolaPriceSingle), ticketPriceBundle: Number(tombolaPriceBundle), maxTickets: Number(tombolaMaxTickets), minTicketsToStart: Number(tombolaMinStart) }); alert("Configurazione Tombola aggiornata!"); };

    // Seasonality Handlers
    const handleSeasonChange = (field: keyof SeasonTheme, value: any) => {
        if (!seasonConfigForm) return;
        setSeasonConfigForm({
            ...seasonConfigForm,
            seasons: {
                ...seasonConfigForm.seasons,
                [activeSeasonTab]: { ...seasonConfigForm.seasons[activeSeasonTab], [field]: value }
            }
        });
    };
    const handleEmojiChange = (val: string) => {
        setEmojiInput(val);
        const emojis = val.split(',').map(e => e.trim()).filter(e => e !== '');
        handleSeasonChange('emojis', emojis);
    };
    const saveSeasonality = async () => {
        if (seasonConfigForm) {
            await onUpdateSeasonality(seasonConfigForm);
            alert("Configurazione stagionale salvata!");
        }
    };
    const changeSeasonTab = (season: 'winter'|'spring'|'summer'|'autumn') => {
        setActiveSeasonTab(season);
        if(seasonConfigForm && seasonConfigForm.seasons && seasonConfigForm.seasons[season]) {
            setEmojiInput(seasonConfigForm.seasons[season].emojis.join(', '));
        }
    };

    const TabButton = ({ tab, label, icon }: { tab: AdminTab, label: string, icon: React.ReactNode }) => (
        <button onClick={() => setActiveTab(tab)} className={`flex flex-col items-center justify-center p-2 rounded-lg transition-all w-16 h-14 md:w-20 md:h-16 text-[9px] md:text-[10px] font-bold gap-1 ${activeTab === tab ? 'bg-red-500 text-white shadow-md scale-105' : 'bg-white text-slate-500 hover:bg-red-50 hover:text-red-500 border border-slate-100'}`}>
            <div className={`${activeTab === tab ? 'text-white' : 'text-current'} transform scale-75 md:scale-90`}>{icon}</div>
            <span className="text-center leading-tight">{label}</span>
        </button>
    );

    if (!isAuthenticated) return (
        <div className="flex flex-col items-center justify-center min-h-screen bg-slate-100 p-4">
            <div className="bg-white p-8 rounded-2xl shadow-xl max-w-md w-full text-center border-t-4 border-red-500">
                <h2 className="text-2xl font-bold mb-6 text-slate-800">Area Amministrativa</h2>
                <div className="flex gap-2"><button type="button" onClick={onGoBack} className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl">Indietro</button><button type="button" onClick={onLogin} className="flex-1 py-3 bg-white border border-slate-200 text-slate-700 font-bold rounded-xl hover:bg-slate-50 flex items-center justify-center gap-2 shadow-sm"><GoogleIcon className="h-5 w-5" /> Accedi con Google</button></div>
            </div>
        </div>
    );

    return (
        <div className="min-h-screen bg-slate-50 flex flex-col font-sans">
            <header className="bg-white border-b border-slate-200 p-3 sticky top-0 z-50">
                <div className="flex flex-col gap-3 max-w-7xl mx-auto w-full">
                    <div className="flex items-center justify-between w-full">
                         <button onClick={onGoBack} className="flex items-center text-slate-500 hover:text-slate-800 font-bold gap-1 text-sm"><BackArrowIcon className="h-4 w-4" /> Esci</button>
                        <div className="bg-slate-800 text-white px-4 py-1.5 rounded-full shadow-lg flex flex-col items-center">
                            <span className="text-[9px] uppercase text-slate-400 font-bold tracking-wider">Saldo Cassa</span>
                            <span className="text-lg font-black leading-none">€{(currentBalance || 0).toFixed(2)}</span>
                        </div>
                        <div className="text-right"><p className="text-[9px] text-slate-400 uppercase font-bold">{isSuperAdmin ? 'Super Admin' : 'Admin'}</p><button onClick={onLogout} className="text-[10px] text-red-500 font-bold hover:underline">LOGOUT</button></div>
                    </div>
                    <div className="flex flex-wrap justify-center gap-2 w-full">
                        <TabButton tab="movements" label="Movimenti" icon={<ListIcon className="h-6 w-6" />} />
                        <TabButton tab="stock" label="Stock" icon={<BoxIcon className="h-6 w-6" />} />
                        <TabButton tab="products" label="Prodotti" icon={<StarIcon className="h-6 w-6" />} />
                        <TabButton tab="staff" label="Staff" icon={<StaffIcon className="h-6 w-6" />} />
                        <TabButton tab="cash" label="Cassa" icon={<CashIcon className="h-6 w-6" />} />
                        <TabButton tab="settings" label="Config" icon={<SettingsIcon className="h-6 w-6" />} />
                        <TabButton tab="admins" label="Admin" icon={<UserPlusIcon className="h-6 w-6" />} />
                        <TabButton tab="extra" label="Giochi" icon={<SparklesIcon className="h-6 w-6" />} />
                    </div>
                </div>
            </header>

            <main className="flex-grow p-4 md:p-6 max-w-7xl mx-auto w-full">
                {activeTab === 'movements' && (
                    <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
                        <div className="p-4 border-b border-slate-100 bg-slate-50">
                            <div className="flex flex-wrap gap-4 items-end justify-between">
                                <h2 className="font-bold text-lg text-slate-700">Gestione Movimenti</h2>
                                <div className="flex gap-2 items-center">
                                    <div><label className="text-[9px] uppercase font-bold text-slate-400 block">Data</label><input type="date" value={movFilterDate} onChange={e => setMovFilterDate(e.target.value)} className="border rounded px-2 py-1 text-sm bg-white" /></div>
                                    <div><label className="text-[9px] uppercase font-bold text-slate-400 block">Turno</label><select value={movFilterShift} onChange={e => setMovFilterShift(e.target.value as any)} className="border rounded px-2 py-1 text-sm bg-white"><option value="all">Tutti</option><option value="a">A</option><option value="b">B</option><option value="c">C</option><option value="d">D</option></select></div>
                                </div>
                            </div>
                            {selectedOrderIds.size > 0 && <button onClick={handleBulkDelete} className="mt-3 w-full bg-red-500 hover:bg-red-600 text-white px-4 py-2 rounded-lg font-bold text-sm flex items-center justify-center gap-2"><TrashIcon className="h-4 w-4" /> Annulla ({selectedOrderIds.size})</button>}
                        </div>
                        <div className="overflow-x-auto max-h-[60vh]">
                            <table className="w-full text-left text-slate-600 text-sm">
                                <thead className="bg-slate-100 text-slate-800 uppercase text-xs sticky top-0 z-10">
                                    <tr>
                                        <th className="p-3 w-8"><input type="checkbox" checked={selectedOrderIds.size === filteredOrders.length && filteredOrders.length > 0} onChange={toggleAllSelection} className="rounded text-red-500 focus:ring-red-500" /></th>
                                        <th className="p-3">Data</th><th className="p-3">Info</th><th className="p-3 text-right">Totale</th><th className="p-3 text-center">Stato</th><th className="p-3 text-center">Azioni</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-slate-100">
                                    {filteredOrders.map(order => (
                                        <tr key={order.id} className={`hover:bg-slate-50 ${order.isDeleted ? 'bg-red-50' : ''}`}>
                                            <td className="p-3"><input type="checkbox" checked={selectedOrderIds.has(order.id)} onChange={() => toggleOrderSelection(order.id)} className="rounded text-red-500 focus:ring-red-500" /></td>
                                            <td className="p-3 whitespace-nowrap text-xs">{editingOrderId === order.id ? (<div className="flex flex-col gap-1"><input type="date" value={editForm.date} onChange={e => setEditForm({...editForm, date: e.target.value})} className="border rounded px-1" /><input type="time" value={editForm.time} onChange={e => setEditForm({...editForm, time: e.target.value})} className="border rounded px-1" /></div>) : new Date(order.timestamp).toLocaleString('it-IT')}{order.deletedBy && <div className="text-[9px] text-red-500 italic mt-1">Del: {order.deletedBy}</div>}</td>
                                            <td className="p-3"><div className={`text-xs font-bold ${order.isDeleted ? 'text-red-800 line-through' : 'text-slate-700'}`}>{order.staffName}</div><div className="text-[10px] text-slate-400 uppercase">Cassa {order.tillId}</div></td>
                                            <td className="p-3 text-right font-bold text-slate-800">{editingOrderId === order.id ? <input type="number" step="0.01" value={editForm.total} onChange={e => setEditForm({...editForm, total: parseFloat(e.target.value)})} className="border rounded px-1 w-20 text-right" /> : <span className={order.isDeleted ? 'line-through opacity-50' : ''}>€{order.total.toFixed(2)}</span>}</td>
                                            <td className="p-3 text-center">{order.isDeleted ? <span className="text-red-500 font-bold text-[10px] uppercase border border-red-200 bg-red-100 px-1 rounded">ANNULLATO</span> : <span className="text-green-500 font-bold text-[10px] uppercase">OK</span>}</td>
                                            <td className="p-3 flex justify-center gap-2">{editingOrderId === order.id ? <button onClick={saveEditOrder}><SaveIcon className="h-5 w-5 text-green-600" /></button> : <>{!order.isDeleted && <button onClick={() => startEditOrder(order)}><EditIcon className="h-4 w-4 text-blue-400" /></button>}{!order.isDeleted && <button onClick={() => handleSingleDelete(order.id)}><TrashIcon className="h-4 w-4 text-red-500" /></button>}{order.isDeleted && isSuperAdmin && <button onClick={() => handlePermanentDelete(order.id)} title="Elimina Definitivamente"><TrashIcon className="h-4 w-4 text-slate-800" /></button>}</>}</td>
                                        </tr>
                                    ))}
                                </tbody>
                            </table>
                        </div>
                    </div>
                )}

                {activeTab === 'stock' && <StockControl products={products} onStockPurchase={onStockPurchase} onStockCorrection={onStockCorrection} />}
                {activeTab === 'products' && <ProductManagement products={products} onAddProduct={onAddProduct} onUpdateProduct={onUpdateProduct} onDeleteProduct={onDeleteProduct} />}
                {activeTab === 'staff' && <StaffManagement staff={staff} onAddStaff={onAddStaff} onUpdateStaff={onUpdateStaff} onDeleteStaff={onDeleteStaff} />}
                {activeTab === 'cash' && <CashManagement orders={orders} movements={cashMovements} onAddMovement={onAddCashMovement} onUpdateMovement={onUpdateMovement} onDeleteMovement={onDeleteMovement} onResetCash={onResetCash} isSuperAdmin={isSuperAdmin} currentUser={currentUser} />}
                {activeTab === 'extra' && <GamesHub onPlayTombola={onNavigateToTombola} tombolaConfig={tombolaConfig} />}

                {activeTab === 'settings' && (
                    <div className="space-y-6">
                        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200">
                            <h2 className="text-lg font-bold text-slate-800 mb-4">Colori Casse</h2>
                            <div className="grid grid-cols-2 gap-4">
                                {tills.map(till => (
                                    <div key={till.id} className="flex items-center justify-between p-3 bg-slate-50 rounded border">
                                        <span className="font-bold text-sm">Turno {till.shift.toUpperCase()}</span>
                                        <input type="color" value={colors[till.id] || '#f97316'} onChange={(e) => handleColorChange(till.id, e.target.value)} className="h-8 w-12 cursor-pointer" />
                                    </div>
                                ))}
                            </div>
                            <button onClick={saveSettings} className="mt-4 w-full bg-slate-800 text-white font-bold py-2 rounded-lg">Salva Colori</button>
                        </div>

                        {/* CONFIGURAZIONE STAGIONALITA' A SCHEDE */}
                        <div className="bg-gradient-to-br from-blue-50 to-indigo-50 p-6 rounded-xl border border-blue-100 shadow-sm">
                            <div className="flex justify-between items-center mb-6">
                                <h2 className="text-lg font-bold text-blue-800 flex items-center gap-2"><SparklesIcon className="h-5 w-5" /> Personalizzazione Stagionale</h2>
                                <div className="flex items-center gap-2 bg-slate-100 p-1 rounded-lg">
                                    <button onClick={() => setSeasonConfigForm(prev => prev ? {...prev, mode: 'auto'} : null)} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${seasonConfigForm?.mode === 'auto' ? 'bg-white shadow text-purple-600' : 'text-slate-400'}`}>Auto</button>
                                    <button onClick={() => setSeasonConfigForm(prev => prev ? {...prev, mode: 'manual'} : null)} className={`px-3 py-1 rounded-md text-xs font-bold transition-all ${seasonConfigForm?.mode === 'manual' ? 'bg-white shadow text-purple-600' : 'text-slate-400'}`}>Manuale</button>
                                </div>
                            </div>
                            <div className="flex gap-2 mb-4 overflow-x-auto pb-2">
                                {(['winter', 'spring', 'summer', 'autumn'] as const).map(s => (
                                    <button key={s} onClick={() => changeSeasonTab(s)} className={`px-4 py-2 rounded-lg text-xs font-bold uppercase tracking-wider transition-colors ${activeSeasonTab === s ? 'bg-purple-100 text-purple-700 border border-purple-200' : 'bg-slate-50 text-slate-500 hover:bg-slate-100'}`}>
                                        {s === 'winter' ? '❄️ Inverno' : s === 'spring' ? '🌸 Primavera' : s === 'summer' ? '☀️ Estate' : '🍂 Autunno'}
                                    </button>
                                ))}
                            </div>
                            {seasonConfigForm && seasonConfigForm.seasons && (
                                <div className="space-y-4 bg-slate-50 p-4 rounded-xl border border-slate-100 animate-fade-in">
                                    <div className="grid grid-cols-2 gap-4">
                                        <div><label className="text-[10px] font-bold text-slate-400 uppercase">Sfondo</label><div className="flex gap-2 mt-1"><input type="color" value={seasonConfigForm.seasons[activeSeasonTab].backgroundColor} onChange={e => handleSeasonChange('backgroundColor', e.target.value)} className="h-8 w-12 cursor-pointer rounded border" /><input type="text" value={seasonConfigForm.seasons[activeSeasonTab].backgroundColor} onChange={e => handleSeasonChange('backgroundColor', e.target.value)} className="w-full border rounded p-1 text-xs font-mono" /></div></div>
                                        <div><label className="text-[10px] font-bold text-slate-400 uppercase">Animazione</label><select value={seasonConfigForm.seasons[activeSeasonTab].animationType} onChange={e => handleSeasonChange('animationType', e.target.value)} className="w-full border rounded p-1.5 text-sm mt-1"><option value="none">Nessuna</option><option value="snow">Neve (Lenta)</option><option value="rain">Pioggia (Veloce)</option><option value="float">Farfalle</option><option value="leaves">Foglie</option></select></div>
                                    </div>
                                    <div><label className="text-[10px] font-bold text-slate-400 uppercase">Emoji (virgola separati)</label><input type="text" value={emojiInput} onChange={e => handleEmojiChange(e.target.value)} className="w-full border rounded p-2 text-lg mt-1" /></div>
                                    {seasonConfigForm.mode === 'manual' && (
                                        <div className="mt-4 pt-4 border-t border-slate-200">
                                            <label className="flex items-center gap-2 cursor-pointer"><input type="radio" name="currentManual" checked={seasonConfigForm.currentManualSeason === activeSeasonTab} onChange={() => setSeasonConfigForm({...seasonConfigForm, currentManualSeason: activeSeasonTab})} className="text-purple-600 focus:ring-purple-500" /><span className="text-sm font-bold text-slate-700">Imposta {activeSeasonTab} come stagione attiva</span></label>
                                        </div>
                                    )}
                                </div>
                            )}
                            <button onClick={saveSeasonality} className="mt-4 w-full bg-purple-600 text-white font-bold py-3 rounded-lg hover:bg-purple-700 shadow-md">Salva Tutto</button>
                        </div>

                        {isSuperAdmin && (
                            <div className="bg-red-50 p-6 rounded-xl border border-red-100">
                                <h2 className="text-lg font-bold text-red-800 mb-4">Zona Pericolo</h2>
                                <div className="flex gap-2 items-end">
                                    <div className="flex-grow"><label className="text-xs font-bold text-red-400 uppercase">Data Limite</label><input type="date" value={massDeleteDate} onChange={e => setMassDeleteDate(e.target.value)} className="w-full border border-red-200 rounded p-2 text-sm" /></div>
                                    <button onClick={() => handleMassDelete('orders')} className="bg-red-600 text-white px-4 py-2 rounded text-xs font-bold hover:bg-red-700">Elimina Ordini</button>
                                    <button onClick={() => handleMassDelete('movements')} className="bg-red-600 text-white px-4 py-2 rounded text-xs font-bold hover:bg-red-700">Elimina Movim.</button>
