                        Scegli il turno per iniziare
                    </p>
                </div>

                {/* GRIGLIA CASSE */}
                <div className="flex flex-wrap justify-center gap-2 w-full mb-3 px-2">
                    {tills.map((till) => {
                        const bgBtnColor = tillColors[till.id] || '#f97316';
